/**
 * decompose-engine.ts —— AI 拆解引擎（纯函数，确定性）
 *
 * 两种模式：
 *  A. 模板模式：克隆模板任务快照 + {{goal}} 占位替换 + 模板依赖索引映射
 *  B. 启发式模式：按标点切分目标 + 关键词估时 + FS 串联依赖 + isShared 检测
 *
 * 排期：与 CPM 集成（calculateCPM），estimateHours → durationDays = hours/8
 */
export interface TemplateTask {
    title: string;
    description?: string | null;
    estimatedHours?: number | null;
    isShared?: boolean;
    priority?: string | null;
}
export interface DecomposeInput {
    goalTitle: string;
    goalDescription?: string;
    templateTasks?: TemplateTask[];
    templateDependencies?: Array<{
        fromIndex: number;
        toIndex: number;
        type: string;
        lagDays?: number;
    }>;
    totalEstimatedHours?: number;
    startDate?: string;
}
export interface DecomposeTask {
    title: string;
    description: string;
    estimatedHours: number;
    isShared: boolean;
    priority: 'urgent' | 'high' | 'medium' | 'low';
    earliestStart?: string;
    earliestFinish?: string;
}
export interface DecomposeDependency {
    fromIndex: number;
    toIndex: number;
    type: 'FS' | 'SS' | 'FF' | 'SF';
    lagDays: number;
}
export interface DecomposeResult {
    summary: string;
    tasks: DecomposeTask[];
    dependencies: DecomposeDependency[];
    warnings: string[];
}
/**
 * 生成拆解建议（纯函数）
 */
export declare function decompose(input: DecomposeInput): DecomposeResult;
/**
 * 对拆解建议做 CPM 排期（就地填充 earliestStart/earliestFinish）
 * @returns 排期结果摘要（每任务的开始/结束日期）
 */
export declare function scheduleDecompose(result: DecomposeResult, options?: {
    startDate?: string;
}): {
    tasks: DecomposeTask[];
    projectEta: string | null;
    criticalPath: string[];
};
